create table if not exists public.recruiting_game_plans (id uuid primary key default gen_random_uuid(), athlete_user_id uuid not null references auth.users(id) on delete cascade, period_start date not null, period_end date not null, goals jsonb not null default '[]'::jsonb, advisor_note text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists recruiting_game_plans_athlete_idx on public.recruiting_game_plans(athlete_user_id,period_start desc);
create table if not exists public.college_discovery_feedback (id uuid primary key default gen_random_uuid(), athlete_user_id uuid not null references auth.users(id) on delete cascade, college_id uuid not null references public.colleges(id) on delete cascade, decision text not null check(decision in ('interested','maybe','not_for_me')), reasons text[] not null default '{}', note text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(athlete_user_id,college_id));
create table if not exists public.relationship_exit_reasons (id uuid primary key default gen_random_uuid(), athlete_user_id uuid not null references auth.users(id) on delete cascade, college_id uuid not null references public.colleges(id) on delete cascade, reasons text[] not null default '{}', note text, created_at timestamptz not null default now());
create table if not exists public.event_debriefs (id uuid primary key default gen_random_uuid(), athlete_user_id uuid not null references auth.users(id) on delete cascade, event_id uuid not null references public.events(id) on delete cascade, coaches_spoken_to text[] not null default '{}', interest_change text check(interest_change in ('more','same','less')), meaningful_notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(athlete_user_id,event_id));
create table if not exists public.parent_guardian_access (id uuid primary key default gen_random_uuid(), athlete_user_id uuid not null references auth.users(id) on delete cascade, parent_user_id uuid not null references auth.users(id) on delete cascade, status text not null default 'pending' check(status in ('pending','active','declined','revoked')), permissions jsonb not null default '{"view_progress":true,"view_fit":true,"view_events":true,"view_connections":true,"manage_calendar":false}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(athlete_user_id,parent_user_id));
create table if not exists public.data_quality_issues (id uuid primary key default gen_random_uuid(), entity_type text not null, entity_id uuid, issue_type text not null, severity text not null default 'warning' check(severity in ('info','warning','error')), details jsonb not null default '{}'::jsonb, status text not null default 'open' check(status in ('open','resolved','ignored')), detected_at timestamptz not null default now(), resolved_at timestamptz);
alter table public.recruiting_game_plans enable row level security; alter table public.college_discovery_feedback enable row level security; alter table public.relationship_exit_reasons enable row level security; alter table public.event_debriefs enable row level security; alter table public.parent_guardian_access enable row level security; alter table public.data_quality_issues enable row level security;
drop policy if exists game_plans_access on public.recruiting_game_plans; create policy game_plans_access on public.recruiting_game_plans for all using (athlete_user_id=auth.uid() or public.can_access_athlete(athlete_user_id)) with check (athlete_user_id=auth.uid() or public.can_access_athlete(athlete_user_id));
drop policy if exists discovery_feedback_access on public.college_discovery_feedback; create policy discovery_feedback_access on public.college_discovery_feedback for all using (athlete_user_id=auth.uid() or public.can_access_athlete(athlete_user_id)) with check (athlete_user_id=auth.uid());
drop policy if exists exit_reasons_access on public.relationship_exit_reasons; create policy exit_reasons_access on public.relationship_exit_reasons for all using (athlete_user_id=auth.uid() or public.can_access_athlete(athlete_user_id)) with check (athlete_user_id=auth.uid());
drop policy if exists event_debriefs_access on public.event_debriefs; create policy event_debriefs_access on public.event_debriefs for all using (athlete_user_id=auth.uid() or public.can_access_athlete(athlete_user_id)) with check (athlete_user_id=auth.uid());
drop policy if exists parent_access_self on public.parent_guardian_access; create policy parent_access_self on public.parent_guardian_access for select using (athlete_user_id=auth.uid() or parent_user_id=auth.uid() or public.can_access_athlete(athlete_user_id));
drop policy if exists parent_access_athlete_write on public.parent_guardian_access; create policy parent_access_athlete_write on public.parent_guardian_access for all using (athlete_user_id=auth.uid()) with check (athlete_user_id=auth.uid());